return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'nqo','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:35+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'ߛߌ߲߬ߞߊ «%1$s» ߡߊ߬ߝߊ߬ߟߋ߲߬ ߘߊߕߐ߫ ߓߟߏ߬ߟߊ߲ %2$s ߞߊ߲߬ ߓߊ ߓߟߏ߬ߟߊ߲ ߡߊ߫ ߞߘߐ߬ߝߊ߬ߟߋ߲ ߘߐߝߍ߬ ߞߊ߲߬ߞߊ߲ ߡߍ߲ ߦߋ߫ ߡߊ߬ߝߊ߬ߟߋ߲ ߡߍ߲ ߘߌ߫. ߞߘߐ߬ߝߊ߬ߟߋ߲ ߘߐߝߍ߬ ߥߟߊ߫ ߊ߬ ߛߓߍ߫ ߦߌߟߊ data-ߥߟߊ߫ aria-ߥߟߊ߫ html- ߛߌ߲߬ߞߊ ߘߌ߫ ߞߊ߬ ߊ߬ ߘߏ߲߫ ߞߎ߲߬ߓߏ߲ ߞߊ߲߬.','This storage key is not declared by the block or its extensions.'=>'ߓߊ߬ߟߊ ߞߎ߲߬ߝߊ߬ߟߋ߲ ߣߌ߲߬ ߡߊ߫ ߟߊ߬ߛߐ߬ߘߐ߲߬ ߓߟߏ߬ߟߊ߲ ߥߟߊ߫ ߊ߬ ߓߊߕߐ߫ ߟߊ߫ ߞߊ߬ߙߌ ߟߊ߫.','This top-level key is not an attribute of the block, so it is ignored.'=>'ߞߋ߬ߞߋ ߣߌ߫ ߓߟߐߞߌ ߟߊ߫ ߕߘߍ߬ߡߊ߲߬ ߕߍ߫، ߏ߬ ߘߏߙߐ߫ ߊ߬ ߡߊ߫ ߓߊߖߌ߫.','This key is only read inside the blockstudio object, which is missing.'=>'ߞߋ߬ߞߋ ߣߌ߫ blockstudio ߞߏ߲߬ߘߏ ߘߐ߫ ߟߊߓߊ߯ߙߊ߫ ߞߍ߫، ߏ߬ ߡߊ߫ ߛߐ߬ߘߐ߲߬.','This value is not among the field options.'=>'ߘߎߢߊ ߣߌ߲߬ ߡߊ߫ ߦߋ߫ ߞߘߐ߬ߝߊ߬ߟߋ߲ ߘߊߕߐ߫ ߟߊ߫.','This value has an unsupported shape for the field.'=>'ߘߎߢߊ ߣߌ߲߬ ߡߊ߫ ߞߘߐ߬ߝߊ߬ߟߋ߲ ߡߊ߬ߝߊ߬ߟߋ߲ ߛߙߋ߬ ߞߣߐߘߐ ߘߏ߫ ߘߌ߫.','This repeater has fewer rows than its minimum.'=>'ߞߐ߲߬ߕߐ߬ߟߌ ߣߌ߲߬ ߘߐ߬ߝߊ߬ߟߌ߬ ߞߐ߲߬ߕߐ߬ߟߌ ߛߌ߲߬ߘߌ ߘߊ߲߬ߘߊ߬ߟߌ ߘߐ.','This repeater has more rows than its maximum.'=>'ߞߐ߲߬ߕߐ߬ߟߌ ߣߌ߲߬ ߘߐ߬ߝߊ߬ߟߌ߬ ߞߐ߲߬ߕߐ߬ߟߌ ߛߌ߲߬ߘߌ ߓߟߏ߬ߟߊ߲ ߞߊ߲߬.','This storage key has conflicting field definitions.'=>'ߓߊ߬ߟߊ ߞߎ߲߬ߝߊ߬ߟߋ߲ ߣߌ߲߬ ߞߘߐ߬ߝߊ߬ߟߋ߲ ߞߊ߲߬ߞߊ߲ ߞߣߐߘߐ߫ ߓߍ߲߬ߓߍ߲ ߠߊ߫.','The nested field value overrides this top-level value.'=>'ߞߣߐ߬ߛߊ߬ߙߊ ߟߊ߬ߞߊ߲߬ߘߊ ߦߋ߫ ߞߎ߲߬ߝߊ߬ߟߋ߲ ߣߌ߲߬ ߞߊ߲߬ ߞߊ߬ ߞߎ߲߬ߘߊ߬ߟߌ ߣߌ߲߬ ߘߊߕߐ߫.','Extension bindings read this value only from blockstudio.attributes.'=>'ߞߊ߬ߙߌ ߓߊߕߐ߫ ߘߐߕߊ߬ ߞߎ߲߬ߝߊ߬ߟߋ߲ ߣߌ߲߬ ߟߊ߫ blockstudio.attributes ߘߐ߫ ߞߊ߬ߙߌ ߘߏ߫ ߡߊ߬.','Blockstudio field values must be stored in an object.'=>'Blockstudio ߞߘߐ߬ߝߊ߬ߟߋ߲ ߘߎߢߊ ߞߊߣߊ߲߫ ߓߊ߬ߟߊ ߞߣߐߘߐ ߘߌ߫.','Blockstudio is preparing its block cache. Please retry shortly.'=>'Blockstudio ߦߋ߫ ߊ߬ ߓߟߏ߬ߟߊ߲ ߞߊ߬ߛߌߦߊ ߟߊ߬ߓߌ߬ߟߌ ߞߊ߫ ߘߌ߫. ߞߊ߬ ߓߌ߬ߟߌ ߞߐ߬ߘߐ߫ ߛߎ߬ߘߎ߬ߘߊ.','Canvas is disabled.'=>'ߞߊ߲߬ߕߏ߬ߟߊ ߓߊ߲߫.','Invalid or missing CSRF token.'=>'CSRF ߛߌ߲߬ߞߊ ߡߊ߬ߞߐ߬ߘߐ߲߬ߕߊ ߥߟߊ߫ ߓߊ߲߫.','Authentication required.'=>'ߞߊ߬ߙߌ߬ߟߌ ߞߊߣߊ߲߫.','Insufficient permissions.'=>'ߡߊ߬ߞߊ߬ߙߊ߲߬ߠߌ ߓߟߏ߬ߟߊ߲ ߡߊ߫ ߓߍ߲߫.','Validation failed.'=>'ߞߊ߬ߙߌ߬ߟߌ ߡߊ߫ ߓߊ߲߫.','Record not found.'=>'ߞߊ߬ߙߌ ߡߊ߫ ߛߐ߬ߘߐ߲߬.','Invalid islands request.'=>'islands ߞߊ߬ߙߌ߬ߟߌ ߡߊ߫ ߓߊ߲߫.','Too many islands requested.'=>'islands ߜߊ߬ߙߊ ߡߊ߫ ߞߊߣߊ߲߫.','Invalid island block.'=>'island ߓߟߏ߬ߟߊ߲ ߡߊ߬ߞߐ߬ߘߐ߲߬ߕߊ.','Invalid island signature.'=>'island ߛߌ߲߬ߞߊ ߡߊ߬ߞߐ߬ߘߐ߲߬ߕߊ.','Sorry, you are not allowed to read blocks of this post.'=>'ߕߊ߬ߡߌ߲߬ߕߊ، ߌ ߡߊ߫ ߓߍ߲߫ ߞߊ߬ ߓߟߏ߬ߟߊ߲ ߘߏ߫ ߟߊߞߊ߲߬ ߞߐ߬ߙߊ߬ߟߌ ߣߌ߲߬ ߞߊ߲߬.','Sorry, you are not allowed to read blocks as this user.'=>'ߕߊ߬ߡߌ߲߬ߕߊ، ߌ ߡߊ߫ ߓߍ߲߫ ߞߊ߬ ߓߟߏ߬ߟߊ߲ ߟߊߞߊ߲߬ ߡߊ߬ߞߊ߬ߙߊ߲߬ߠߌ ߣߌ߲߬ ߞߊ߲߬.','Invalid block.'=>'ߓߟߏ߬ߟߊ߲ ߡߊ߬ߞߐ߬ߘߐ߲߬ߕߊ.','Method not allowed.'=>'ߘߎߡߊ߲߫ ߡߊ߫ ߓߍ߲߫.','Block not found.'=>'ߓߟߏ߬ߟߊ߲ ߡߊ߫ ߛߐ߬ߘߐ߲߬.','Function not found.'=>'ߊ߬ߣߌ߲ ߡߊ߫ ߛߐ߬ߘߐ߲߬.','Function is not callable.'=>'ߊ߬ߣߌ߲ ߡߊ߫ ߓߍ߲߫ ߞߊ߬ ߓߊ߯ ߟߊ߫.','Blockstudio ignored invalid configuration values:'=>'Blockstudio ߓߊ߲߫ ߞߐ߬ߘߐ߲߬ ߞߊ߲߬ߞߊ߲ ߡߊ߬ߞߐ߬ߘߐ߲߬ߕߊ ߓߍ߲߬ߓߍ߲ ߣߌ߲߬:','%s: Link text'=>'%s: ߛߐ߲߬ߘߐ ߞߊ߲߬ߝߏ߫','%s: URL'=>'%s: URL','True'=>'ߊ߬ ߦߋ߫ ߟߋ߬','False'=>'ߊ߬ ߕߍ߫','Could not load database records.'=>'ߞߊ߬ ߓߊ߬ߟߊ ߞߐ߲߬ߞߐ߲߬ ߘߎߢߊ ߘߏ߫ ߟߊߛߐ߬ߘߐ߲߬ ߡߊ߫ ߓߍ߲߫.','This database has no records yet.'=>'ߓߊ߬ߟߊ ߣߌ߲߬ ߞߐ߲߬ߞߐ߲߬ ߡߊ߫ ߘߐ߫ ߡߎߣߎ߲߬.','No Blockstudio databases are registered.'=>'Blockstudio ߓߊ߬ߟߊ ߞߐ߲߬ߞߐ߲߬ ߡߊ߫ ߟߊ߬ߛߐ߬ߘߐ߲߬.','The selected database could not be found.'=>'ߓߊ߬ߟߊ ߡߍ߲ ߛߎ߬ߙߎ߬ߟߌ ߞߊ߲߫ ߡߊ߫ ߛߐ߬ߘߐ߲߬.','Overview'=>'ߞߘߐ߬ߛߊ߬ߙߊ','Registry'=>'ߛߌ߲߬ߘߌ߬ߟߌ','Databases'=>'ߓߊ߬ߟߊ߬ߟߌ','Docs'=>'ߟߊ߬ߞߊ߲߬ߠߌ','No Blockstudio overview data is available.'=>'Blockstudio ߞߘߐ߬ߛߊ߬ߙߊ ߞߊ߬ߙߌ ߡߊ߫ ߓߍ߲߫.','Name'=>'ߕߐ߮','Title'=>'ߕߐ߮','Description'=>'ߞߊ߲߬ߝߏ','Category'=>'ߘߊߦߟߍ','Type'=>'ߛߓߍ߲','Status'=>'ߛߊ߬ߡߊ߲','Installed'=>'ߟߊ߬ߟ